func (s *V2GitStore) fullRefSearchOrder() ([]plumbing.ReferenceName, error) {
	refNames := []plumbing.ReferenceName{plumbing.ReferenceName(paths.V2FullCurrentRefName)}

	archived, err := s.ListArchivedGenerations()
