	}

	result := &SessionContent{}
	sessionFT := s.wrapWithFetcher(ctx, sessionTree)

	if metadataFile, fileErr := sessionFT.File(paths.MetadataFileName); fileErr == nil {
		if content, contentErr := metadataFile.Contents(); contentErr == nil {
